"// Image Magnifier component on hover
function ImageMagnifier({
  src,
  alt,
  className = "",
  magnifierHeight = 150,
  magnifierWidth = 150,
  zoomLevel = 1.8,
  disabled = false
}: {
  src: string;
  alt: string;
  className?: string;
  magnifierHeight?: number;
  magnifierWidth?: number;
  zoomLevel?: number;
  disabled?: boolean;
}) {
  const [[x, y], setXY] = useState([0, 0]);
  const [showMagnifier, setShowMagnifier] = useState(false);
  const [[imgWidth, imgHeight], setSize] = useState([0, 0]);

  return (
    <div
      className={`relative overflow-hidden cursor-crosshair select-none ${className}`}
      onMouseEnter={(e) => {
        if (disabled) return;
        const elem = e.currentTarget;
        const { width, height } = elem.getBoundingClientRect();
        setSize([width, height]);
        setShowMagnifier(true);
      }}
      onMouseMove={(e) => {
        if (disabled) return;
        const elem = e.currentTarget;
        const { top, left } = elem.getBoundingClientRect();
        const xCoord = e.clientX - left;
        const yCoord = e.clientY - top;
        setXY([xCoord, yCoord]);
      }}
      onMouseLeave={() => {
        setShowMagnifier(false);
      }}
    >
      <img
        src={src}
        alt={alt}
        className="w-full h-full object-cover transition-all duration-300"
        style={{
          filter: showMagnifier && !disabled ? "brightness(0.85)" : "none"
        }}
      />

      {showMagnifier && !disabled && (
        <div
